def magic_square(n):
    # Create the model
    model = cp_model.CpModel()

    # Create the variables
    square = {}
    for i in range(n):
        for j in range(n):
            square[(i, j)] = model.NewIntVar(1, n * n, f'square_{i}_{j}')

    # Each cell contains a different integer
    for i in range(n):
        for j in range(n):
            for k in range(n):
                for l in range(j + 1, n):
                    model.Add(square[(i, j)] != square[(i, l)])
            for k in range(i + 1, n):
                for l in range(n):
                    model.Add(square[(i, j)] != square[(k, l)])

    # The sum of integers in each row is equal
    target_sum = n * (n * n + 1) // 2
    for i in range(n):
        model.Add(sum(square[(i, j)] for j in range(n)) == target_sum)

    # The sum of integers in each column is equal
    for j in range(n):
        model.Add(sum(square[(i, j)] for i in range(n)) == target_sum)

    # The sum of integers in the main diagonal is equal
    model.Add(sum(square[(i, i)] for i in range(n)) == target_sum)

    # The sum of integers in the other diagonal is equal
    model.Add(sum(square[(i, n - i - 1)] for i in range(n)) == target_sum)

    # Solve the model
    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        solution = [[solver.Value(square[(i, j)]) for j in range(n)] for i in range(n)]
