from ortools.sat.python import cp_model
import json

# Input data
n_slots = 9  # The amount of slots on a template
n_templates = 2  # The amount of templates
n_var = 7  # The amount of different variations
demand = [250, 255, 260, 500, 500, 800, 1100]  # The demand per variation

# Create the model
model = cp_model.CpModel()

# Create variables
x = {}
for t in range(n_templates):
    for v in range(n_var):
        x[(t, v)] = model.NewIntVar(0, n_slots, f'x_{t}_{v}')

y = {}
for t in range(n_templates):
    for v in range(n_var):
        y[(t, v)] = model.NewBoolVar(f'y_{t}_{v}')

z = model.NewIntVar(0, sum(demand), 'z')

# Constraints
for v in range(n_var):
    model.Add(sum(x[(t, v)] for t in range(n_templates)) == demand[v])

for t in range(n_templates):
    model.Add(sum(x[(t, v)] for v in range(n_var)) <= n_slots)

for t in range(n_templates):
    for v in range(n_var):
        model.Add(x[(t, v)] <= n_slots * y[(t, v)])

for t in range(n_templates):
    model.Add(sum(y[(t, v)] for v in range(n_var)) <= n_slots)

# Objective
model.Minimize(z)

# Solve
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    production = sum(demand) // n_slots + (1 if sum(demand) % n_slots > 0 else 0)
    layout = {}
    for t in range(n_templates):
        layout[t] = {}
        for v in range(n_var):
            if solver.Value(y[(t, v)]) == 1:
                layout[t][v] = solver.Value(x[(t, v)])
    solution = {
        'production': production,
        'layout': layout
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
