# Input data
n_boats = 5  # Number of boats
n_periods = 4  # Number of periods
capacity = [6, 8, 12, 12, 12]  # Capacities of the boats
crew_size = [2, 2, 2, 2, 4]  # Crew sizes of the boats

# Create the model
model = cp_model.CpModel()

# Create variables
is_host = [model.NewBoolVar(f'is_host_{i}') for i in range(n_boats)]
visits = [[model.NewBoolVar(f'visit_{i}_{j}_{k}') for k in range(n_boats)] for i in range(n_boats) for j in range(n_periods)]

# Constraints
for i in range(n_boats):
    for j in range(n_periods):
        for k in range(n_boats):
            model.Add(visits[i][j][k] <= is_host[k])  # A boat can only be visited if it is a host

for i in range(n_boats):
    for j in range(n_periods):
        model.Add(sum(visits[i][j][k] for k in range(n_boats)) <= 1)  # A boat can only visit one host per period

for i in range(n_boats):
    for k in range(n_boats):
        model.Add(sum(visits[i][j][k] for j in range(n_periods)) <= 1)  # A boat cannot visit the same host twice

