def solve_block_puzzle():
    # Create the model
    model = cp_model.CpModel()

    # Define the variables
    block = {}
    for letter in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
        if letter not in 'QZ':
            block[letter] = model.NewIntVar(0, 3, letter)

    # Each block can have at most 6 letters
    for b in range(4):
        model.Add(sum(block[letter] == b for letter in block) <= 6)

    # Each letter can be on at most one block
    for letter in block:
        model.Add(sum(block[letter] == b for b in range(4)) == 1)

    # Define the words
    words = ['BAKE', 'ONYX', 'ECHO', 'OVAL', 'GIRD', 'SMUG', 'JUMP', 'TORN', 'LUCK', 'VINY', 'LUSH', 'WRAP']

    # Each word must be able to be spelled using the blocks
    for word in words:
        model.Add(sum(block[letter] == block[word[0]] for letter in word) <= 1)
        for i in range(1, len(word)):
            model.Add(sum(block[letter] == block[word[i]] for letter in word[:i]) <= 1)

    # Solve the model
    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        solution = [solver.Value(block[letter]) for letter in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ' if letter not in 'QZ']
