    for i in range(n):
        for j in range(n):
            x[(i, j)] = model.NewIntVar(1, n * n, f'x_{i}_{j}')

    # Create the constraints
    for i in range(n):
        for j in range(n):
            # Each number can only be used once
            for k in range(n):
                for l in range(n):
                    if (i, j) != (k, l):
                        model.Add(x[(i, j)] != x[(k, l)])

    # Movement constraints
    for i in range(n):
        for j in range(n):
            for num in range(1, n * n):
                if (i, j) != (0, 0):
                    # Check horizontal movement
                    if j >= 3:
                        model.Add(x[(i, j)] - x[(i, j - 3)] == 1).OnlyEnforceIf(x[(i, j)] > 0)
                    # Check vertical movement
