                    # Check diagonal movement (top-left to bottom-right)
                    if i >= 2 and j >= 2:
                        model.Add(x[(i, j)] - x[(i - 2, j - 2)] == 1).OnlyEnforceIf(x[(i, j)] > 0)
                    # Check diagonal movement (bottom-left to top-right)
